const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry - area between Elkhorn and Platte Rivers near Omaha
  const omaha = ee.Geometry.Polygon([
    [[-96.2, 41.15], [-96.2, 41.35], [-95.8, 41.35], [-95.8, 41.15], [-96.2, 41.15]]
  ]);

  // 2. Helper function to calculate water extent
  function calculateWaterExtent(startDate, endDate, label) {
    const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(omaha)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    const size = collection.size().getInfo();
    console.log(`${label} Images found: ${size}`);

    if (size === 0) {
      // Try Landsat 8 as fallback
      const landsatCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(omaha)
        .filterDate(startDate, endDate)
        .filter(ee.Filter.lt('CLOUD_COVER', 30));

      const lSize = landsatCol.size().getInfo();
      console.log(`${label} Landsat fallback: ${lSize} images`);

      if (lSize === 0) {
        return { valid: false, reason: 'C1' };
      }

      // Use Landsat
      const image = landsatCol.median();
      const green = image.select('SR_B3').multiply(0.0000275).add(-0.2);
      const swir = image.select('SR_B6').multiply(0.0000275).add(-0.2);
      const mndwi = green.subtract(swir).divide(green.add(swir));
      const water = mndwi.gt(0);

      const stats = water.reduceRegion({
        reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
        geometry: omaha,
        scale: 3000,
        maxPixels: 1e9
      });

      const waterPixels = stats.get('sum').getInfo();
      const totalPixels = stats.get('count').getInfo();

      console.log(`${label} Water pixels: ${waterPixels}, Total: ${totalPixels}`);

      if (totalPixels === 0) {
        return { valid: false, reason: 'C2' };
      }

      return { valid: true, waterPixels: waterPixels || 0 };
    }

    // Use Sentinel-2
    const image = collection.median();
    const green = image.select('B3').multiply(0.0001);
    const swir = image.select('B11').multiply(0.0001);
    const mndwi = green.subtract(swir).divide(green.add(swir));
    const water = mndwi.gt(0);

    const stats = water.reduceRegion({
      reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
      geometry: omaha,
      scale: 3000,
      maxPixels: 1e9
    });

    const waterPixels = stats.get('sum').getInfo();
    const totalPixels = stats.get('count').getInfo();

    console.log(`${label} Water pixels: ${waterPixels}, Total: ${totalPixels}`);

    if (totalPixels === 0) {
      return { valid: false, reason: 'C2' };
    }

    return { valid: true, waterPixels: waterPixels || 0 };
  }

  // 3. Calculate water extent for both periods
  const march2018 = calculateWaterExtent('2018-03-01', '2018-03-31', 'March 2018');

  if (!march2018.valid) {
    console.log(`<answer>${march2018.reason}</answer>`);
    return;
  }

  const march2019 = calculateWaterExtent('2019-03-10', '2019-03-22', 'March 16 2019');

  if (!march2019.valid) {
    console.log(`<answer>${march2019.reason}</answer>`);
    return;
  }

  // 4. Compare water extents
  const pixels2018 = march2018.waterPixels;
  const pixels2019 = march2019.waterPixels;

  if (pixels2018 === null || pixels2019 === null || isNaN(pixels2018) || isNaN(pixels2019)) {
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`2018 water: ${pixels2018} pixels`);
  console.log(`2019 water: ${pixels2019} pixels`);
  console.log(`Difference: ${pixels2019 - pixels2018} pixels`);

  if (pixels2019 > pixels2018) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
